   132	            match column.default.as_ref().map(|v| v.datatype()) {
   133	                None if column.nullable => {
   134	                    return errinput!("nullable column {cname} must have a default value");
   135	                }
   136	                Some(None) if !column.nullable => {
   137	                    return errinput!("invalid NULL default for non-nullable column {cname}");
   138	                }
   139	                Some(Some(vtype)) if vtype != column.datatype => {
   140	                    return errinput!("invalid default type {vtype} for {ctype} column {cname}");
   141	                }
   142	                Some(_) | None => {}
   143	            }
